import { puzzleFinishes } from './themes.js';
export const puzzleGames={
 huarong:{name:'华容道',english:'SLIDING BLOCKS',description:'移开层层木块，让曹操走出方寸。',rules:'点击木块选中，用方向键或方向按钮移动一格。木块不能重叠。把「曹操」移动到底边中央出口即可通关。'},
 sokoban:{name:'推箱子',english:'SOKOBAN',description:'一步一思量，把木箱送回原位。',rules:'方向键或按钮移动人物。木箱只能推、不能拉；将所有木箱推到圆形目标上即可通关。走入死角时可撤销。'},
 tangram:{name:'七巧板',english:'TANGRAM',description:'七片木色，拼出完整的一方天地。',rules:'拖动七片拼板，拼满中央正方形。点击选中后可旋转或翻面。方向与位置接近正确时自动吸附；「拼合提示」可显示各片轮廓。'},
 nonogram:{name:'数织',english:'NONOGRAM',description:'循着数字，把藏在格中的图案织出来。',rules:'行列数字表示连续涂色格的长度，多段之间至少留一格。点击格子涂色；切换「标空」可标记空白。填出全部正确色格即可完成。'},
 sudoku:{name:'数独',english:'SUDOKU',description:'九行九列，让每个数字各得其所。',rules:'每行、每列和每个粗框九宫内，数字 1–9 各出现一次。先选空格，再点击数字或键盘输入。红色表示当前行、列或宫中存在重复数字。'},
 hanoi:{name:'河内塔',english:'TOWER OF HANOI',description:'把一叠圆盘，安静地移向另一端。',rules:'点击柱子取最上层圆盘，再点击目标柱。每次移动一片，大盘不能放在小盘上。把所有圆盘移动到最右侧柱子即可通关。'}
};
const colors=['#b98b61','#7e9985','#ccaa63','#9b879b','#7d9aa4','#bb8172','#a5a56f'];
const blockStart=[['曹操',1,0,2,2],['关羽',1,2,2,1],['张飞',0,0,1,2],['赵云',3,0,1,2],['马超',0,2,1,2],['黄忠',3,2,1,2],['兵',1,3,1,1],['兵',2,3,1,1],['兵',1,4,1,1],['兵',2,4,1,1]];
const maps=[['#######','#  .  #','#  $  #','# .$. #','#  $@ #','#     #','#######'],['#######','# . . #','# $ $ #','#  @  #','#     #','#######'],['########','#      #','# .$$. #','#  @   #','#      #','########']];
const grids=[['00100','01110','11111','00100','00100'],['01010','11111','11111','01110','00100'],['00100','01110','11111','01010','11011']];
const sudokuSource=['530070000600195000098000060800060003400803001700020006060000280000419005000080079','003020600900305001001806400008102900700000008006708200002609500800203009005010300'];
const polygons=['0,0 4,0 2,2','0,0 2,2 0,4','4,4 4,2 2,4','4,0 4,2 3,1','2,2 3,1 4,2 3,3','2,2 3,3 1,3','0,4 1,3 3,3 2,4'];
const clone=x=>JSON.parse(JSON.stringify(x));
export class PuzzleRoom{
 constructor(host,onBack){this.host=host;this.onBack=onBack;this.level=0;this.kind='';this.history=[];this.finishByKind={};try{this.finishByKind=JSON.parse(localStorage.getItem('chess-cheers-finishes')||'{}')||{};}catch{}this.view3D=true;this.viewAngle='angle';this.viewZoom=1;this.keyHandler=e=>{if(host.hidden||e.target.matches('input,select'))return;const dirs={ArrowUp:[0,-1],ArrowDown:[0,1],ArrowLeft:[-1,0],ArrowRight:[1,0]};if(dirs[e.key]&&['huarong','sokoban'].includes(this.kind)){e.preventDefault();this.move(...dirs[e.key]);}else if(this.kind==='sudoku'&&/^[1-9]$/.test(e.key))this.number(+e.key);else if(this.kind==='sudoku'&&['Backspace','Delete','0'].includes(e.key))this.number(0);};document.addEventListener('keydown',this.keyHandler);}
 open(kind){this.kind=kind;this.finish=puzzleFinishes[this.finishByKind[kind]]?this.finishByKind[kind]:({sudoku:'ceramic',nonogram:'garden',sokoban:'garden'}[kind]||'wood');this.level=0;this.reset();}
 reset(){this.history=[];this.steps=0;this.selected=null;this.won=false;this.mark=false;this.hint=false;
 if(this.kind==='huarong')this.state=clone(blockStart);
 if(this.kind==='sokoban'){this.map=maps[this.level%maps.length];this.state={boxes:[],player:0};this.map.forEach((r,y)=>[...r].forEach((c,x)=>{if(c==='$')this.state.boxes.push(y*20+x);if(c==='@')this.state.player=y*20+x;}));}
 if(this.kind==='nonogram')this.state=Array(25).fill(0);
 if(this.kind==='sudoku'){this.givens=[...sudokuSource[this.level%sudokuSource.length]].map(Number);this.state=[...this.givens];}
 if(this.kind==='hanoi'){this.count=3+this.level%4;this.state=[Array.from({length:this.count},(_,i)=>this.count-i),[],[]];}
 if(this.kind==='tangram')this.state=polygons.map((_,i)=>({x:(i%3-1)*95,y:(i<3?-1:1)*90,a:(i%4)*90,flip:false,locked:false}));this.render();}
 save(){this.history.push({state:clone(this.state),steps:this.steps});this.steps++;}
 undo(){const old=this.history.pop();if(old){this.state=old.state;this.steps=old.steps;this.won=false;this.selected=null;this.render();}}
 move(dx,dy){if(this.won)return;if(this.kind==='huarong'){if(this.selected===null)return;const b=this.state[this.selected],nx=b[1]+dx,ny=b[2]+dy;if(nx<0||ny<0||nx+b[3]>4||ny+b[4]>5)return;const collision=this.state.some((o,i)=>i!==this.selected&&nx<o[1]+o[3]&&nx+b[3]>o[1]&&ny<o[2]+o[4]&&ny+b[4]>o[2]);if(collision)return;this.save();b[1]=nx;b[2]=ny;this.won=this.state[0][1]===1&&this.state[0][2]===3;}
 if(this.kind==='sokoban'){const p=this.state.player,n=p+dx+dy*20,b=n+dx+dy*20,wall=v=>this.map[Math.floor(v/20)]?.[v%20]===undefined||this.map[Math.floor(v/20)][v%20]==='#';if(wall(n))return;const i=this.state.boxes.indexOf(n);if(i>=0&&(wall(b)||this.state.boxes.includes(b)))return;this.save();if(i>=0)this.state.boxes[i]=b;this.state.player=n;this.won=this.state.boxes.every(v=>this.map[Math.floor(v/20)][v%20]==='.');}this.render();}
 number(n){if(this.selected===null||this.givens[this.selected]||this.won)return;this.save();this.state[this.selected]=n;this.won=this.state.every(Boolean)&&this.state.every((v,i)=>!this.conflict(i));this.render();}
 conflict(i){return !!this.state[i]&&this.state.some((v,j)=>j!==i&&v===this.state[i]&&(Math.floor(i/9)===Math.floor(j/9)||i%9===j%9||Math.floor(i/27)===Math.floor(j/27)&&Math.floor(i%9/3)===Math.floor(j%9/3)));}
 render(){const g=puzzleGames[this.kind];this.host.innerHTML=`<div class="play-heading"><button class="back-button" data-action="back">← 返回大厅</button><span class="eyebrow">THE QUIET PUZZLE COLLECTION</span><button class="text-button" data-tutorial="${this.kind}">教程与教学</button></div><section class="puzzle-layout"><div class="puzzle-surface" data-finish="${this.finish}"><div class="puzzle-caption">弈间 · 方寸巧思 <span>${g.english}</span></div><div class="puzzle-materials" role="group" aria-label="游戏材质">${Object.entries(puzzleFinishes).map(([id,f])=>`<button data-action="finish:${id}" aria-pressed="${this.finish===id}"><i class="finish-dot ${id}"></i>${f.name}</button>`).join('')}</div><div class="puzzle-view-switch" role="group" aria-label="棋盘视角"><button data-action="view2d" aria-pressed="${!this.view3D}">2D 平面</button><button data-action="view3d" aria-pressed="${this.view3D}">3D 立体 ↗</button></div><div class="puzzle-3d-host" ${this.view3D?'':'hidden'} aria-label="${g.name}三维棋盘，拖动空白处旋转视角，点击棋子操作"></div><div id="puzzle-canvas" class="puzzle-canvas ${this.kind}" aria-label="${g.name}棋盘"></div><div class="puzzle-camera-tools" ${this.view3D?'':'hidden'}><div role="group" aria-label="三维观察方向"><button data-camera="angle">斜看</button><button data-camera="top">俯看</button><button data-camera="front">正面</button><button data-camera="side">侧面</button></div><label>放大 <input id="puzzle-3d-zoom" type="range" min="80" max="150" step="5" value="${this.viewZoom*100}" aria-label="三维棋盘缩放"><output>${this.viewZoom.toFixed(2)}×</output></label><small>拖动空白处环绕 · 滚轮或双指缩放</small></div><p class="puzzle-foot">${puzzleFinishes[this.finish].note}</p></div><aside class="puzzle-panel"><span class="eyebrow">A LITTLE ROOM FOR THOUGHT</span><h1>${g.name}</h1><p class="puzzle-intro">${g.description}</p><p class="puzzle-rules">${g.rules}</p><div class="puzzle-status" role="status" aria-live="polite">${this.won?'✧ 解开了，思考有了回响。':this.kind==='huarong'&&this.selected===null?'先选一块木牌，再移动它。':'慢慢想，下一步就在眼前。'}<small>${this.steps} 步 · 第 ${this.level+1} 关${this.kind==='hanoi'?' · 最少 '+(2**this.count-1)+' 步':''}</small></div><div id="puzzle-controls"></div><div class="puzzle-actions"><button data-action="undo" ${this.history.length?'':'disabled'}>↶ 撤销</button><button data-action="reset">↻ 重置</button>${['sokoban','nonogram','sudoku','hanoi'].includes(this.kind)?'<button data-action="next">下一关 →</button>':''}</div><p class="puzzle-local">进度保留在本次页面会话中</p></aside></section>`;
 const board=this.host.querySelector('#puzzle-canvas'),controls=this.host.querySelector('#puzzle-controls');
 if(['huarong','sokoban'].includes(this.kind))controls.innerHTML='<div class="puzzle-arrows"><button data-dir="0,-1" aria-label="向上">↑</button><button data-dir="-1,0" aria-label="向左">←</button><button data-dir="0,1" aria-label="向下">↓</button><button data-dir="1,0" aria-label="向右">→</button></div><small>也可使用键盘方向键</small>';
 if(this.kind==='huarong'){board.innerHTML=this.state.map((b,i)=>`<button class="wood-block ${this.selected===i?'picked':''}" data-piece="${i}" style="left:${b[1]*25}%;top:${b[2]*20}%;width:${b[3]*25}%;height:${b[4]*20}%;--wood:${colors[i%7]}">${b[0]}</button>`).join('')+'<span class="block-exit">出口 ↓</span>';}
 if(this.kind==='sokoban'){board.style.setProperty('--cols',this.map[0].length);board.innerHTML=this.map.flatMap((r,y)=>[...r].map((c,x)=>{const v=y*20+x;return `<div class="warehouse-cell ${c==='#'?'wall':''} ${c==='.'?'goal':''}">${this.state.player===v?'<span class="warehouse-player">●</span>':this.state.boxes.includes(v)?'<span class="warehouse-box">✧</span>':c==='.'?'○':''}</div>`;})).join('');}
 if(this.kind==='nonogram'){const target=grids[this.level%grids.length],runs=a=>a.join('').split('0').filter(Boolean).map(s=>s.length).join(' · ')||'0';board.innerHTML='<span></span>'+Array.from({length:5},(_,x)=>`<span class="weave-clue">${runs(target.map(r=>r[x]))}</span>`).join('')+target.map((r,y)=>`<span class="weave-clue">${runs([...r])}</span>`+[...r].map((_,x)=>`<button data-cell="${y*5+x}" class="weave-cell ${this.state[y*5+x]===1?'ink':''}" aria-label="第${y+1}行第${x+1}列">${this.state[y*5+x]===2?'×':''}</button>`).join('')).join('');controls.innerHTML=`<button class="puzzle-toggle" data-action="mark" aria-pressed="${this.mark}">${this.mark?'× 标空模式':'■ 涂色模式'} · 点击切换</button>`;}
 if(this.kind==='sudoku'){board.innerHTML=this.state.map((v,i)=>`<button data-cell="${i}" class="sudoku-cell ${this.givens[i]?'given':''} ${this.selected===i?'picked':''} ${this.conflict(i)?'conflict':''}" style="${i%9===2||i%9===5?'border-right:2px solid #8d8f77;':''}${Math.floor(i/9)===2||Math.floor(i/9)===5?'border-bottom:2px solid #8d8f77;':''}" aria-label="第${Math.floor(i/9)+1}行第${i%9+1}列${v?' 数字'+v:' 空格'}">${v||''}</button>`).join('');controls.innerHTML='<div class="puzzle-numbers">'+Array.from({length:9},(_,i)=>`<button data-number="${i+1}">${i+1}</button>`).join('')+'<button data-number="0">清除</button></div>';}
 if(this.kind==='hanoi'){board.innerHTML=this.state.map((peg,i)=>`<button class="hanoi-peg ${this.selected===i?'picked':''}" data-peg="${i}" aria-label="${['左','中','右'][i]}柱，${peg.length}片圆盘"><span class="hanoi-rod"></span>${peg.map((size,j)=>`<span class="hanoi-disk" style="width:${25+size/this.count*70}%;bottom:${12+j*11}%;background:${colors[size%7]}">${size}</span>`).join('')}<small>${['起点','中转','终点'][i]}</small></button>`).join('');}
 if(this.kind==='tangram'){board.innerHTML=`<svg viewBox="-115 -115 430 430" aria-label="拖动七巧板到正方形轮廓中"><rect x="0" y="0" width="200" height="200" class="tangram-target"/>${this.hint?polygons.map(p=>`<polygon points="${p.split(' ').map(q=>q.split(',').map(Number).map(v=>v*50).join(',')).join(' ')}" class="tangram-hint"/>`).join(''):''}${this.state.map((p,i)=>`<g data-tan="${i}" transform="translate(${p.x} ${p.y}) translate(100 100) rotate(${p.a}) scale(${p.flip?-1:1} 1) translate(-100 -100)"><polygon points="${polygons[i].split(' ').map(q=>q.split(',').map(Number).map(v=>v*50).join(',')).join(' ')}" fill="${colors[i]}" class="tan ${this.selected===i?'picked':''}"/><text x="${polygons[i].split(' ').reduce((a,q)=>a+Number(q.split(',')[0])*50,0)/polygons[i].split(' ').length}" y="${polygons[i].split(' ').reduce((a,q)=>a+Number(q.split(',')[1])*50,0)/polygons[i].split(' ').length}">${i+1}</text></g>`).join('')}</svg>`;controls.innerHTML='<div class="puzzle-actions"><button data-action="rotate">旋转 90°</button><button data-action="flip">翻面</button><button data-action="hint">拼合提示</button></div>';this.bindDrag(board);}
 board.hidden=this.view3D;if(this.view3D)this.attach3D();this.host.querySelectorAll('[data-camera]').forEach(b=>b.onclick=()=>{this.viewAngle=b.dataset.camera;this.scene3D?.preset(this.viewAngle);this.scene3D?.zoom(this.viewZoom);});const zoom=this.host.querySelector('#puzzle-3d-zoom');zoom.oninput=()=>{this.viewZoom=Number(zoom.value)/100;zoom.nextElementSibling.textContent=this.viewZoom.toFixed(2)+'×';this.scene3D?.zoom(this.viewZoom);};
 this.host.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>this.action(b.dataset.action));this.host.querySelectorAll('[data-dir]').forEach(b=>b.onclick=()=>this.move(...b.dataset.dir.split(',').map(Number)));this.host.querySelectorAll('[data-piece]').forEach(b=>b.onclick=()=>{this.selected=+b.dataset.piece;this.render();});this.host.querySelectorAll('[data-number]').forEach(b=>b.onclick=()=>this.number(+b.dataset.number));this.host.querySelectorAll('[data-cell]').forEach(b=>b.onclick=()=>{const i=+b.dataset.cell;if(this.kind==='sudoku'){this.selected=i;this.render();}else if(!this.won){this.save();this.state[i]=this.state[i]===(this.mark?2:1)?0:this.mark?2:1;this.won=this.state.every((v,j)=>(v===1)===(grids[this.level%grids.length][Math.floor(j/5)][j%5]==='1'));this.render();}});this.host.querySelectorAll('[data-peg]').forEach(b=>b.onclick=()=>{const i=+b.dataset.peg;if(this.won)return;if(this.selected===null){if(this.state[i].length)this.selected=i;}else{const from=this.state[this.selected],to=this.state[i];if(i!==this.selected&&(!to.length||from.at(-1)<to.at(-1))){this.save();to.push(from.pop());this.won=this.state[2].length===this.count;}this.selected=null;}this.render();});}
 attach3D(){const host=this.host.querySelector('.puzzle-3d-host');this.scenePromise??=import('./puzzles-3d.js');this.scenePromise.then(({Puzzle3D})=>{if(!host.isConnected)return;try{if(!this.scene3D)this.scene3D=new Puzzle3D();this.scene3D.attach(host,this);}catch{this.view3D=false;this.render();}}).catch(()=>{if(host.isConnected){this.view3D=false;this.render();}});}
 action(a){if(a.startsWith('finish:')){const id=a.split(':')[1];if(puzzleFinishes[id]){this.finish=id;this.finishByKind[this.kind]=id;try{localStorage.setItem('chess-cheers-finishes',JSON.stringify(this.finishByKind));}catch{}this.render();}return;}if(a==='view2d'||a==='view3d'){this.view3D=a==='view3d';this.render();}if(a==='back')this.onBack();if(a==='reset')this.reset();if(a==='undo')this.undo();if(a==='next'){this.level++;this.reset();}if(a==='mark'){this.mark=!this.mark;this.render();}if(a==='hint'){this.hint=!this.hint;this.render();}if(['rotate','flip'].includes(a)&&this.selected!==null&&!this.state[this.selected].locked){this.save();const p=this.state[this.selected];if(a==='rotate')p.a=(p.a+90)%360;else p.flip=!p.flip;this.snap(p);this.render();}}
 snap(p){if(Math.abs(p.x)<12&&Math.abs(p.y)<12&&p.a===0&&!p.flip){Object.assign(p,{x:0,y:0,locked:true});}this.won=this.state.every(p=>p.locked);}
 bindDrag(board){const svg=board.querySelector('svg');svg.querySelectorAll('[data-tan]').forEach(el=>el.onpointerdown=e=>{const i=+el.dataset.tan,p=this.state[i];if(p.locked||this.won)return;e.preventDefault();this.selected=i;const start={x:e.clientX,y:e.clientY,px:p.x,py:p.y},scale=430/svg.getBoundingClientRect().width;this.save();el.setPointerCapture(e.pointerId);el.onpointermove=ev=>{p.x=Math.max(-110,Math.min(110,start.px+(ev.clientX-start.x)*scale));p.y=Math.max(-110,Math.min(110,start.py+(ev.clientY-start.y)*scale));el.setAttribute('transform',`translate(${p.x} ${p.y}) translate(100 100) rotate(${p.a}) scale(${p.flip?-1:1} 1) translate(-100 -100)`);};el.onpointerup=()=>{this.snap(p);this.render();};el.onpointercancel=()=>this.render();});}
}
export function puzzleArt(kind){let art='';
 if(kind==='huarong')art='<g transform="translate(49 15)"><rect width="122" height="150" rx="7" fill="#baa780"/>'+[[3,3,28,57],[33,3,56,57],[91,3,28,57],[3,62,28,57],[33,62,56,27],[91,62,28,57],[33,91,27,27],[62,91,27,27],[3,122,28,25],[91,122,28,25]].map(([x,y,w,h],i)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="3" fill="${colors[i%7]}" stroke="#f5e8cf" stroke-width="1.5"/>`).join('')+'</g>';
 if(kind==='sokoban')art='<g transform="translate(45 35) rotate(-8 70 60)"><rect width="130" height="115" rx="5" fill="#b8c4a5"/>'+Array.from({length:20},(_,i)=>`<rect x="${i%5*26+1}" y="${Math.floor(i/5)*28+1}" width="24" height="26" fill="${[0,1,2,3,4,5,10,15,19].includes(i)?'#839578':'#e2e3cc'}"/>`).join('')+'<circle cx="91" cy="70" r="10" fill="none" stroke="#9ba974" stroke-width="2"/><rect x="55" y="36" width="22" height="22" rx="2" fill="#bf9c69" stroke="#8b774d"/><path d="M58 39l16 16m0-16L58 55" stroke="#e3cc9d"/><circle cx="40" cy="77" r="9" fill="#b47c60"/></g>';
 if(kind==='tangram')art='<g transform="translate(51 28) rotate(-8 60 60) scale(30)">'+polygons.map((p,i)=>`<polygon points="${p}" fill="${colors[i]}" stroke="#faf3e1" stroke-width=".04"/>`).join('')+'</g>';
 if(kind==='nonogram')art='<g transform="translate(50 27)">'+grids[1].flatMap((r,y)=>[...r].map((n,x)=>`<rect x="${x*25}" y="${y*25}" width="22" height="22" rx="2" fill="${n==='1'?'#829879':'#e4e4d2'}"/>`)).join('')+'</g>';
 if(kind==='sudoku')art='<g transform="translate(48 25)"><rect width="126" height="126" rx="4" fill="#eaede3" stroke="#8d9e9b"/>'+[8,2,6,3,5,7,4,9,1].map((n,i)=>`<text x="${i%3*42+21}" y="${Math.floor(i/3)*42+28}" fill="${i%3===1?'#b09264':'#768e91'}" font-size="23" font-family="Georgia" text-anchor="middle">${n}</text>`).join('')+'<path d="M42 0v126M84 0v126M0 42h126M0 84h126" stroke="#b7c2b7"/></g>';
 if(kind==='hanoi')art='<g transform="translate(20 24)"><rect x="0" y="121" width="180" height="8" rx="3" fill="#a68c65"/>'+[30,90,150].map(x=>`<rect x="${x-3}" y="5" width="6" height="120" rx="3" fill="#b69c70"/>`).join('')+[[30,109,54,0],[30,94,43,2],[30,79,32,1],[150,109,27,4]].map(([x,y,w,i])=>`<rect x="${x-w/2}" y="${y}" width="${w}" height="13" rx="5" fill="${colors[i]}" stroke="#fff2"/>`).join('')+'</g>';
 return `<div class="puzzle-card-art illustrated"><svg viewBox="0 0 220 180" aria-hidden="true"><ellipse cx="110" cy="156" rx="72" ry="8" fill="#8b795c12"/>${art}</svg><small>${puzzleGames[kind].english}</small></div>`;
}
